cat > tests/site.test.ts <<'EOF'
import { expect, it } from 'bun:test'
import { testSite } from 'kay/test'
import { contact } from '../src/routes/contact.kay'

const site = await testSite()

it('answers 404 for an unknown book', async () => {
  const page = await site.visit('/books/nope')
  expect(page.status).toBe(404)
  expect(page.html).toContain('Back to the books')
  expect(page.html).not.toContain('aria-current')
})

it('accepts a valid message from an island call', async () => {
  const result = await site.call(contact, { name: ' Ada ', email: 'ada@example.com', message: 'A message long enough to send.' })
  expect(result.name).toBe('Ada')
})

it('thanks the sender without JavaScript', async () => {
  const page = await site.submit(contact, { name: 'Ada', email: 'ada@example.com', message: 'A message long enough to send.' }, { from: '/contact' })
  expect(page.html).toContain('Thanks, <!--[-->Ada<!--]-->! Your message has been sent.')
})
EOF
