cat > tests/pages.test.ts <<'EOF'
import { expect, it } from 'bun:test'
import { testSite } from 'kay/test'
import { send } from '../src/routes/contact.kay'

const site = await testSite()

it('marks the current section', async () => {
  const current = async (path: string) => (await site.visit(path)).find('nav[aria-label="Main"] a[aria-current="page"]').map(a => a.text)

  expect(await current('/')).toEqual([])
  expect(await current('/books')).toEqual(['Books'])
  expect(await current('/books/dracula')).toEqual(['Books'])
  expect(await current('/books/nope')).toEqual([])
  expect(await current('/about')).toEqual(['About'])
  expect(await current('/contact')).toEqual(['Contact'])
})

it('answers unknown paths with the 404 page', async () => {
  for (const path of ['/nope', '/books/nope']) {
    const page = await site.visit(path)
    expect(page.status).toBe(404)
    expect(page.title()).toBe('Not found | Bookshelf')
  }
})

it('lists the top rated books', async () => {
  const page = await site.visit('/')
  expect(page.title()).toBe('Bookshelf')
  expect(page.find('ol li a').map(a => a.text)).toEqual(['Frankenstein', 'Pride and Prejudice', 'Dracula'])
})

it('checks the contact form on the server', async () => {
  const refused = await site.submit(send, { name: '', email: '', message: 'short' }, { from: '/contact' })
  expect(refused.find('.error').map(p => p.text)).toEqual(['Name is required.', 'Email is required.', 'Message must be at least 20 characters.'])

  const sent = await site.submit(send, { name: ' Ann ', email: 'ann@example.com', message: 'A message long enough to pass.' }, { from: '/contact' })
  expect(sent.find('p[role="status"]')[0]?.text).toBe('Thanks, Ann! Your message has been sent.')

  const data = new FormData()
  data.set('name', 'Bo')
  data.set('email', 'bo@example.com')
  data.set('message', 'Another message long enough.')
  expect(await site.call(send, data)).toEqual({ name: 'Bo' })
})
EOF
bun test 2>&1 | tail -8; bun run check 2>&1 | tail -5

